#include <stdio.h>

#define JOURS    5
#define SERVEURS 4

int main(void)
{
    float temperatures[JOURS][SERVEURS];
    int i, j, chaudes = 0;
    float maximum;

    for (i = 0; i < JOURS; i++) {
        for (j = 0; j < SERVEURS; j++) {
            printf("Jour %d, serveur %d : ", i + 1, j + 1);
            scanf("%f", &temperatures[i][j]);
        }
    }

    printf("\nReleve des temperatures :\n");
    for (i = 0; i < JOURS; i++) {
        for (j = 0; j < SERVEURS; j++)
            printf("%8.1f", temperatures[i][j]);
        printf("\n");
    }

    printf("\nTemperature moyenne de chaque serveur :\n");
    for (j = 0; j < SERVEURS; j++) {
        float somme = 0;
        for (i = 0; i < JOURS; i++)
            somme += temperatures[i][j];
        printf("  serveur %d : %.2f C\n", j + 1, somme / JOURS);
    }

    maximum = temperatures[0][0];
    for (i = 0; i < JOURS; i++)
        for (j = 0; j < SERVEURS; j++) {
            if (temperatures[i][j] > 30.0)
                chaudes++;
            if (temperatures[i][j] > maximum)
                maximum = temperatures[i][j];
        }

    printf("\nReleves au-dessus de 30 C : %d\n", chaudes);
    printf("Temperature maximale : %.1f C\n", maximum);
    return 0;
}

#include <stdio.h>

#define UTILISATEURS 4
#define JOURS        5

int totalUtilisateur(int tentatives[][JOURS], int ligne);

int main(void)
{
    int tentatives[UTILISATEURS][JOURS];
    int i, j, total, meilleur = 0, record;

    for (i = 0; i < UTILISATEURS; i++) {
        for (j = 0; j < JOURS; j++) {
            printf("Utilisateur %d, jour %d : ", i + 1, j + 1);
            scanf("%d", &tentatives[i][j]);
        }
    }

    printf("\nTentatives de connexion :\n");
    for (i = 0; i < UTILISATEURS; i++) {
        for (j = 0; j < JOURS; j++)
            printf("%5d", tentatives[i][j]);
        printf("\n");
    }

    printf("\nTotal par utilisateur :\n");
    record = totalUtilisateur(tentatives, 0);
    for (i = 0; i < UTILISATEURS; i++) {
        total = totalUtilisateur(tentatives, i);
        printf("  utilisateur %d : %d tentative(s)\n", i + 1, total);
        if (total > record) {
            record = total;
            meilleur = i;
        }
    }

    printf("\nPlus grand nombre de tentatives : utilisateur %d (%d)\n",
           meilleur + 1, record);
    return 0;
}

int totalUtilisateur(int tentatives[][JOURS], int ligne)
{
    int j, somme = 0;
    for (j = 0; j < JOURS; j++)
        somme += tentatives[ligne][j];
    return somme;
}

